<template>
  <div class="device-manage">
    <title-line :title="title" />
    <div class="device-list">
      <van-tabs v-model="active">
        <van-tab :title="'全部设备('+deviceList.length+')'">
          <div class="list-dom">
            <div v-for="item in deviceList" :key="item.device_id" class="item">
              <div class="icon" />
              <div class="info">
                <div class="first-line">
                  <div class="name">{{ item.device_name }}</div>
                  <div class="status_green">{{ item.device_model }}</div>
                </div>
                <div class="second-line">{{ item.create_time }}</div>
                <div class="third-line" @click="selectDevice(item)">{{ '开启提现授权' }}</div>
              </div>
            </div>
          </div>
        </van-tab>
        <van-tab :title="'可提现设备('+deviceList.filter(item => item.withdrawal_status === '1').length+')'">
          <div class="list-dom">
            <div v-for="item in deviceList" :key="item.device_id" class="item" />
          </div>
        </van-tab>
        <van-tab :title="'不可提现设备('+deviceList.filter(item => item.withdrawal_status === '0').length+')'" />
      </van-tabs>
      <van-popup v-model="showDialog" position="bottom" @close="showDialog=false">
        <edit-status @close="showDialog=false;getListData()" />
      </van-popup>
    </div>
  </div>
</template>
<script>
import TitleLine from '../modules/TitleLine'
import { updateDevice, getvisitlist } from '@/api/user'
import editStatus from './deviceEditStatus'
export default {
  components: {
    TitleLine,
    editStatus
  },
  data() {
    return {
      active: 0,
      title: '提现设备安全管理',
      showDialog: false,
      currentDevice: {},
      deviceList: [{
        device_id: '123456',
        device_name: 'iphone11 pro',
        device_model: '2', // 1pc 2安卓 3苹果
        chrome_name: 'chrome',
        withdrawal_status: '1', // 1:可提现 0:不可提现
        login_status: '1', // 1:可登录 0:不可登录
        create_time: '2021-01-01 12:00:00',
        suid: '1234567890',
        ip: '192.168.1.1',
        update_time: '2021-01-01 12:00:00'
      }]
    }
  },
  watch: {
  },
  created() {
    getvisitlist().then(res => {
        debugger
        this.deviceList = res.data
    })
  },
  mounted() {
  },
  methods: {
    selectDevice(item) {
      this.currentDevice = item
      this.showDialog = true
    }
  }

}
</script>
